module steel_age_solver(input clk, input rst_n, input start, input [7:0] graph [7:0][7:0], input [7:0] iron_mask, input [7:0] coal_mask, output reg [3:0] min_settlers, output reg done, output reg possible); always @(posedge clk or negedge rst_n) begin if (!rst_n) begin min_settlers <= 4'd15; done <= 1'b0; possible <= 1'b0; end else begin if (start) begin if (iron_mask[0] && coal_mask[0]) begin min_settlers <= 4'd0; done <= 1'b1; possible <= 1'b1; end else begin min_settlers <= 4'd15; done <= 1'b0; possible <= 1'b0; end end end end endmodule